### 7. **No Error Handling** (OWASP A05:2021 - Security Misconfiguration)

**Issue:** No error handling middleware, which could lead to:
- Stack traces exposed to users
- Unstructured error responses
- Information leakage

**Recommendation:** Implement proper error handling.

**Code Example:**
```javascript
// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Async handler wrapper
const asyncHandler = (fn) => (req, res, next) => {
  Promise.resolve(fn(req, res, next)).catch(next);
};

// 404 handler
app.use((req, res, next) => {
  const error = new AppError(`Not found - ${req.originalUrl}`, 404);
  next(error);
});

// Global error handler
app.use((err, req, res, next) => {
  // Log error for debugging (use proper logging in production)
  console.error(err);

  // Don't leak error details in production
  const statusCode = err.statusCode || 500;
  const message = err.isOperational 
    ? err.message 
    : 'Internal server error';

  res.status(statusCode).json({
    error: message,
    ...(process.env.NODE_ENV !== 'production' && { 
      stack: err.stack,
      details: err 
    }),
  });
});
```

---

### 8. **No Logging/monitoring** (OWASP A09:2021 - Security Logging and Monitoring Failures)

**Issue:** No logging or monitoring infrastructure for security events.

**Recommendation:** Implement comprehensive logging.

**Code Example:**
```javascript
const morgan = require('morgan');
const winston = require('winston');

// Create logger
const logger = winston.createLogger({
  level: process.env.LOG_LEVEL || 'info',
  format: winston.format.combine(
    winston.format.timestamp(),
    winston.format.json()
  ),
  transports: [
    new winston.transports.Console(),
    // Add file transport for production
    new winston.transports.File({ 
      filename: 'logs/error.log', 
      level: 'error' 
    }),
    new winston.transports.File({ 
      filename: 'logs/combined.log' 
    }),
  ],
});

// HTTP request logging
app.use(morgan('combined', {
  stream: { write: (message) => logger.info(message.trim()) }
}));

// Security event logging helper
const logSecurityEvent = (event, details) => {
  logger.warn('Security Event', {
    event,
    ...details,
    timestamp: new Date().toISOString(),
  });
};

// Example usage in authentication
// logSecurityEvent('LOGIN_ATTEMPT', { email: req.body.email, ip: req.ip });
```

