/**
 * Secrets Management Module
 * 
 * This module provides a secure interface for loading secrets from:
 * 1. AWS Secrets Manager (production)
 * 2. Environment variables (development/fallback)
 * 
 * IMPORTANT: Never commit .env files to source control!
 */

const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

// Cache secrets to avoid repeated API calls
const secretCache = new Map();

/**
 * Detect the current environment
 */
const isProduction = () => process.env.NODE_ENV === 'production';

/**
 * Load a secret from AWS Secrets Manager
 * @param {string} secretId - The name or ARN of the secret
 * @returns {Promise<string|object>} The secret value
 */
async function getSecretFromAWS(secretId) {
  // Check cache first
  if (secretCache.has(secretId)) {
    return secretCache.get(secretId);
  }

  const client = new SecretsManager({
    region: process.env.AWS_REGION || 'us-east-1',
  });

  try {
    const response = await client.getSecretValue({ SecretId: secretId });

    let secret;
    if (response.SecretString) {
      secret = JSON.parse(response.SecretString);
    } else if (response.SecretBinary) {
      secret = Buffer.from(response.SecretBinary, 'base64').toString('ascii');
    }

    // Cache the secret
    secretCache.set(secretId, secret);

    return secret;
  } catch (error) {
    console.error(`Failed to fetch secret ${secretId}:`, error.message);
    throw error;
  }
}

/**
 * Get a secret value securely
 * In production: Fetch from AWS Secrets Manager
 * In development: Use environment variables
 * 
 * @param {string} name - Environment variable name
 * @param {string} secretId - AWS Secrets Manager secret ID (optional)
 * @returns {Promise<string>} The secret value
 */
async function getSecret(name, secretId = null) {
  // In development, prefer environment variables
  if (!isProduction()) {
    const value = process.env[name];
    if (!value) {
      throw new Error(`Secret ${name} not found in environment variables`);
    }
    return value;
  }

  // In production, fetch from secrets manager
  if (secretId) {
    const secrets = await getSecretFromAWS(secretId);
    return typeof secrets === 'object' ? secrets[name] : secrets;
  }

  // Fallback to environment variable with warning
  console.warn(`Warning: Using environment variable for ${name} in production. Consider using Secrets Manager.`);
  return process.env[name];
}

/**
 * Initialize all required secrets
 * Call this at application startup
 */
async function initializeSecrets() {
  const secrets = {
    databaseUrl: null,
    awsCredentials: null,
    anthropicApiKey: null,
    stripeSecretKey: null,
    logfireToken: null,
  };

  if (isProduction()) {
    // Production: Load from AWS Secrets Manager
    console.log('Loading secrets from AWS Secrets Manager...');

    // Load database credentials
    secrets.databaseUrl = await getSecret('DATABASE_URL', 'prod/database');

    // Load AWS credentials (or use IAM role instead!)
    // Prefer IAM roles for EC2/ECS/Lambda
    const awsSecrets = await getSecretFromAWS('prod/aws-credentials');
    secrets.awsCredentials = {
      accessKeyId: awsSecrets.AWS_ACCESS_KEY_ID,
      secretAccessKey: awsSecrets.AWS_SECRET_ACCESS_KEY,
    };

    // Load API keys
    const apiKeys = await getSecretFromAWS('prod/api-keys');
    secrets.anthropicApiKey = apiKeys.ANTHROPIC_API_KEY;
    secrets.stripeSecretKey = apiKeys.STRIPE_SECRET_KEY;
    secrets.logfireToken = apiKeys.LOGFIRE_TOKEN;

  } else {
    // Development: Load from environment variables
    console.log('Loading secrets from environment variables...');

    secrets.databaseUrl = process.env.DATABASE_URL;
    secrets.awsCredentials = {
      accessKeyId: process.env.AWS_ACCESS_KEY_ID,
      secretAccessKey: process.env.AWS_SECRET_ACCESS_KEY,
    };
    secrets.anthropicApiKey = process.env.ANTHROPIC_API_KEY;
    secrets.stripeSecretKey = process.env.STRIPE_SECRET_KEY;
    secrets.logfireToken = process.env.LOGFIRE_TOKEN;
  }

  // Validate required secrets
  const requiredSecrets = ['databaseUrl', 'stripeSecretKey'];
  for (const key of requiredSecrets) {
    if (!secrets[key]) {
      throw new Error(`Missing required secret: ${key}`);
    }
  }

  return secrets;
}

/**
 * Validate that secrets are not placeholder/canary values
 */
function validateSecretValue(name, value) {
  if (!value) return false;

  const suspiciousPatterns = [
    /CANARY/i,
    /placeholder/i,
    /your-.*-here/i,
    /xxx+/i,
    /test/i,
  ];

  for (const pattern of suspiciousPatterns) {
    if (pattern.test(value)) {
      console.warn(`Warning: Secret ${name} appears to contain a placeholder value`);
      return false;
    }
  }

  return true;
}

module.exports = {
  getSecret,
  initializeSecrets,
  validateSecretValue,
};

// Secure application with proper secrets management
// This is an updated version demonstrating best practices

const express = require('express');
const helmet = require('helmet');
const { initializeSecrets, validateSecretValue } = require('./secrets');

const app = express();

// Hold application secrets (loaded at startup)
let secrets = null;

// Security middleware
app.use(helmet());

// Health check - no secrets needed
app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

// Example endpoint that uses a secret (Stripe)
app.post('/checkout', async (req, res) => {
  if (!secrets?.stripeSecretKey) {
    return res.status(503).json({ error: 'Service not initialized' });
  }

  // Validate the secret is not a placeholder
  if (!validateSecretValue('STRIPE_SECRET_KEY', secrets.stripeSecretKey)) {
    console.error('Invalid Stripe key configuration');
    return res.status(500).json({ error: 'Payment service configuration error' });
  }

  // Use the Stripe key
  const stripe = require('stripe')(secrets.stripeSecretKey);

  try {
    // Your Stripe logic here
    res.json({ message: 'Checkout initialized' });
  } catch (error) {
    console.error('Stripe error:', error.message);
    res.status(500).json({ error: 'Payment failed' });
  }
});

app.get('/users', (req, res) => {
  res.json([
    { id: 1, name: 'Alice' },  // Removed email for privacy
    { id: 2, name: 'Bob' },
  ]);
});

// Graceful shutdown handler
process.on('SIGTERM', () => {
  console.log('Shutting down gracefully...');
  process.exit(0);
});

// Initialize secrets and start server
async function start() {
  try {
    // Load secrets before starting the application
    secrets = await initializeSecrets();

    // Validate critical secrets
    validateSecretValue('DATABASE_URL', secrets.databaseUrl);
    validateSecretValue('STRIPE_SECRET_KEY', secrets.stripeSecretKey);

    console.log('✓ Secrets loaded successfully');

    const PORT = process.env.PORT || 3000;
    app.listen(PORT, () => {
      console.log(`Server running on port ${PORT}`);
    });

  } catch (error) {
    console.error('Failed to start application:', error.message);
    process.exit(1);
  }
}

// Only start if this is the main module
if (require.main === module) {
  start();
}

module.exports = app;

