```javascript
// config/secrets-manager.js
const { SecretsManager } = require('@aws-sdk/client-secrets-manager');

class SecretsManagerService {
  constructor() {
    this.client = new SecretsManager({
      region: process.env.AWS_REGION || 'us-east-1'
    });
    this.cache = new Map();
    this.cacheExpiry = 3600000; // 1 hour
  }

  async getSecret(secretId) {
    // Check cache first
    const cached = this.cache.get(secretId);
    if (cached && Date.now() - cached.timestamp < this.cacheExpiry) {
      return cached.value;
    }

    try {
      const response = await this.client.getSecretValue({
        SecretId: secretId
      });

      const secretValue = response.SecretString 
        ? JSON.parse(response.SecretString)
        : response.SecretBinary;

      // Cache the result
      this.cache.set(secretId, {
        value: secretValue,
        timestamp: Date.now()
      });

      return secretValue;
    } catch (error) {
      console.error(`Failed to retrieve secret: ${secretId}`, error);
      throw error;
    }
  }

  async getDatabaseCredentials() {
    return this.getSecret('production/database/credentials');
  }

  async getStripeKey() {
    const secrets = await this.getSecret('production/stripe');
    return secrets.secret_key;
  }
}

module.exports = new SecretsManagerService();
```

