const express = require('express');
const helmet = require('helmet');
const rateLimit = require('express-rate-limit');
const cors = require('cors');
const app = express();

// -----------------------------------------------
// 1. SECURITY HEADERS (OWASP A05:2021)
// -----------------------------------------------
// Install: npm install helmet

app.use(helmet({
  contentSecurityPolicy: {
    directives: {
      defaultSrc: ["'self'"],
      styleSrc: ["'self'", "'unsafe-inline'"],
      scriptSrc: ["'self'"],
      imgSrc: ["'self'", 'data:', 'https:'],
      connectSrc: ["'self'"],
      fontSrc: ["'self'"],
      objectSrc: ["'none'"],
      mediaSrc: ["'self'"],
      frameSrc: ["'none'"],
    },
  },
  crossOriginEmbedderPolicy: true,
  crossOriginOpenerPolicy: true,
  crossOriginResourcePolicy: { policy: "same-origin" },
  dnsPrefetchControl: { allow: false },
  frameguard: { action: 'deny' },
  hidePoweredBy: true,
  hsts: { maxAge: 31536000, includeSubDomains: true, preload: true },
  ieNoOpen: true,
  noSniff: true,
  originAgentCluster: true,
  permittedCrossDomainPolicies: { permittedPolicies: "none" },
  referrerPolicy: { policy: "strict-origin-when-cross-origin" },
  xssFilter: true,
}));

// -----------------------------------------------
// 2. RATE LIMITING (OWASP A07:2021 - Identification and Authentication Failures)
// -----------------------------------------------
// Install: npm install express-rate-limit

const limiter = rateLimit({
  windowMs: 15 * 60 * 1000, // 15 minutes
  max: 100, // Limit each IP to 100 requests per windowMs
  message: { error: 'Too many requests, please try again later.' },
  standardHeaders: true,
  legacyHeaders: false,
  // Use a secure key generator (don't use IP directly in production behind proxies)
  keyGenerator: (req) => {
    return req.ip || req.connection.remoteAddress;
  },
});

app.use(limiter);

// Stricter rate limit for authentication endpoints
const authLimiter = rateLimit({
  windowMs: 15 * 60 * 1000,
  max: 5, // Only 5 attempts per 15 minutes
  message: { error: 'Too many authentication attempts, please try again later.' },
});

// -----------------------------------------------
// 3. CORS CONFIGURATION
// -----------------------------------------------
// Install: npm install cors

const corsOptions = {
  origin: process.env.ALLOWED_ORIGINS?.split(',') || ['https://yourdomain.com'],
  methods: ['GET', 'POST', 'PUT', 'DELETE'],
  allowedHeaders: ['Content-Type', 'Authorization'],
  credentials: true,
  maxAge: 86400, // 24 hours
  optionsSuccessStatus: 204,
};

app.use(cors(corsOptions));

// -----------------------------------------------
// 4. INPUT VALIDATION & SANITIZATION (OWASP A03:2021 - Injection)
// -----------------------------------------------
// Install: npm install express-validator

const { body, param, query, validationResult } = require('express-validator');

// Validation middleware
const validate = (req, res, next) => {
  const errors = validationResult(req);
  if (!errors.isEmpty()) {
    return res.status(400).json({ 
      error: 'Validation failed', 
      details: errors.array() 
    });
  }
  next();
};

// Example: Validated endpoint
app.get('/users/:id', 
  param('id')
    .isInt({ min: 1, max: 999999 })
    .withMessage('ID must be a positive integer'),
  validate,
  (req, res) => {
    // Safe to use req.params.id
    res.json({ id: req.params.id, name: 'User' });
  }
);

// -----------------------------------------------
// 5. INPUT SANITIZATION (Prevent XSS)
// -----------------------------------------------
// Install: npm install xss

const xss = require('xss');

const sanitizeInput = (req, res, next) => {
  if (req.body) {
    for (let key in req.body) {
      if (typeof req.body[key] === 'string') {
        req.body[key] = xss(req.body[key]);
      }
    }
  }
  next();
};

app.use(express.json({ limit: '10kb' })); // Limit body size
app.use(sanitizeInput);

// -----------------------------------------------
// 6. ERROR HANDLING (OWASP A09:2021 - Security Logging and Monitoring Failures)
// -----------------------------------------------

// Custom error class
class AppError extends Error {
  constructor(message, statusCode) {
    super(message);
    this.statusCode = statusCode;
    this.isOperational = true;
    Error.captureStackTrace(this, this.constructor);
  }
}

// Global error handler
app.use((err, req, res, next) => {
  // Don't leak error details in production
  const isProduction = process.env.NODE_ENV === 'production';

  const statusCode = err.statusCode || 500;

  // Log error (use proper logging library in production)
  console.error({
    message: err.message,
    stack: isProduction ? undefined : err.stack,
    path: req.path,
    method: req.method,
    timestamp: new Date().toISOString(),
  });

  res.status(statusCode).json({
    error: isProduction ? 'An error occurred' : err.message,
    ...(isProduction ? {} : { stack: err.stack }),
  });
});

// -----------------------------------------------
// 7. REQUEST LOGGING (OWASP A09:2021)
// -----------------------------------------------
// Install: npm install morgan winston

const morgan = require('morgan');

// Don't log sensitive data
app.use(morgan('combined', {
  skip: (req) => {
    // Don't log health check endpoints
    return req.path === '/health';
  }
}));

// -----------------------------------------------
// 8. SECURE HEALTH ENDPOINT
// -----------------------------------------------

app.get('/health', (req, res) => {
  res.json({ status: 'ok', timestamp: new Date().toISOString() });
});

